package com.nexamart.backend.repository;import com.nexamart.backend.domain.Address;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.util.*;public interface AddressRepository extends JpaRepository<Address,Long>{Optional<Address> findFirstByCustomerIdAndDefaultAddressTrue(Long customerId);List<Address> findByCustomerId(Long customerId);@Modifying(flushAutomatically=true)@Query("update Address a set a.label = null, a.recipientName = 'Deleted customer', a.phone = null, a.addressLine = '[Deleted]', a.city = null, a.state = null, a.postalCode = null, a.latitude = null, a.longitude = null, a.defaultAddress = false where a.customer.id = :customerId")int anonymizeByCustomerId(@Param("customerId") Long customerId);}
